use std::io::{self, Read, Write};
use std::os::unix::io::AsRawFd;
use termios::{tcsetattr, tcgetattr, TCSAFLUSH, ICANON, ECHO, ISIG, IXON, INPCK, ISTRIP, CS8, VMIN, VTIME};
use libc::{STDIN_FILENO, STDOUT_FILENO};

pub struct Terminal {
    original_termios: termios::Termios,
}

impl Terminal {
    pub fn new() -> io::Result<Self> {
        // Get original terminal settings
        let original_termios = tcgetattr(STDIN_FILENO)
            .map_err(|_| io::Error::last_os_error())?;

        let mut new_termios = original_termios.clone();

        // Disable canonical mode and echo
        new_termios.c_lflag &= !(ICANON | ECHO | ISIG);
        new_termios.c_iflag &= !(IXON | INPCK | ISTRIP);
        new_termios.c_oflag &= !libc::OPOST;
        new_termios.c_cflag |= CS8;
        new_termios.c_cc[VMIN] = 0;
        new_termios.c_cc[VTIME] = 0;

        // Set the new terminal settings
        tcsetattr(STDIN_FILENO, TCSAFLUSH, &new_termios)
            .map_err(|_| io::Error::last_os_error())?;

        Ok(Terminal {
            original_termios,
        })
    }

    pub fn enable_raw_mode(&mut self) -> io::Result<()> {
        let mut termios = tcgetattr(STDIN_FILENO)
            .map_err(|_| io::Error::last_os_error())?;

        termios.c_lflag &= !(ICANON | ECHO | ISIG);
        termios.c_iflag &= !(IXON | INPCK | ISTRIP);
        termios.c_oflag &= !libc::OPOST;
        termios.c_cflag |= CS8;
        termios.c_cc[VMIN] = 0;
        termios.c_cc[VTIME] = 0;

        tcsetattr(STDIN_FILENO, TCSAFLUSH, &termios)
            .map_err(|_| io::Error::last_os_error())?;

        Ok(())
    }

    pub fn get_size(&self) -> io::Result<(u16, u16)> {
        #[cfg(unix)]
        {
            let mut ws: libc::winsize = unsafe { std::mem::zeroed() };
            if unsafe { libc::ioctl(STDOUT_FILENO, libc::TIOCGWINSZ, &mut ws) } == 0 {
                Ok((ws.ws_col, ws.ws_row))
            } else {
                Err(io::Error::last_os_error())
            }
        }
        #[cfg(not(unix))]
        {
            Ok((80, 24))
        }
    }
}

impl Drop for Terminal {
    fn drop(&mut self) {
        // Restore original terminal settings
        let _ = tcsetattr(STDIN_FILENO, TCSAFLUSH, &self.original_termios);
    }
}
EOF

