cat > /workspace/src/buffer.rs << 'EOF'
use std::collections::VecDeque;
use std::fs;
use std::io;

#[derive(Clone, Debug)]
pub enum EditAction {
    InsertChar { pos: (usize, usize), ch: char },
    DeleteChar { pos: (usize, usize), ch: char },
    InsertLine { line_idx: usize, content: String },
    DeleteLine { line_idx: usize, content: String },
    SplitLine { line_idx: usize, col: usize },
    MergeLine { line_idx: usize, content: String },
}

pub struct TextBuffer {
    pub lines: Vec<String>,
    pub cx: usize,
    pub cy: usize,
    pub filepath: Option<String>,
    pub is_dirty: bool,
    pub undo_stack: VecDeque<EditAction>,
    pub redo_stack: VecDeque<EditAction>,
    pub offset_y: usize,
}

impl TextBuffer {
    pub fn new() -> Self {
        TextBuffer {
            lines: vec![String::new()],
            cx: 0,
            cy: 0,
            filepath: None,
            is_dirty: false,
            undo_stack: VecDeque::new(),
            redo_stack: VecDeque::new(),
            offset_y: 0,
        }
    }

    pub fn from_file(filepath: String) -> io::Result<Self> {
        let content = fs::read_to_string(&filepath)?;
        let lines: Vec<String> = if content.is_empty() {
            vec![String::new()]
        } else {
            content.lines().map(|s| s.to_string()).collect()
        };

        Ok(TextBuffer {
            lines,
            cx: 0,
            cy: 0,
            filepath: Some(filepath),
            is_dirty: false,
            undo_stack: VecDeque::new(),
            redo_stack: VecDeque::new(),
            offset_y: 0,
        })
    }

    pub fn save(&mut self) -> io::Result<()> {
        if let Some(ref filepath) = self.filepath {
            let content = self.lines.join("\n");
            fs::write(filepath, content)?;
            self.is_dirty = false;
        }
        Ok(())
    }

    pub fn insert_char(&mut self, ch: char) {
        if self.cy >= self.lines.len() {
            self.lines.push(String::new());
        }

        let action = EditAction::InsertChar {
            pos: (self.cx, self.cy),
            ch,
        };

        let line = &mut self.lines[self.cy];
        if self.cx > line.len() {
            self.cx = line.len();
        }

        line.insert(self.cx, ch);
        self.cx += 1;
        self.is_dirty = true;
        self.redo_stack.clear();
        self.undo_stack.push_back(action);

        if self.undo_stack.len() > 1000 {
            self.undo_stack.pop_front();
        }
    }

