use std::io::{self, Read};

#[derive(Debug, Clone, PartialEq)]
pub enum Key {
    Char(char),
    CtrlA, CtrlB, CtrlC, CtrlD, CtrlE, CtrlF, CtrlG, CtrlH, CtrlI, CtrlJ,
    CtrlK, CtrlL, CtrlM, CtrlN, CtrlO, CtrlP, CtrlQ, CtrlR, CtrlS, CtrlT,
    CtrlU, CtrlV, CtrlW, CtrlX, CtrlY, CtrlZ, CtrlLeftBracket, CtrlRightBracket,
    Escape,
    Alt(Box<Key>),
    Up, Down, Left, Right,
    Home, End, PageUp, PageDown,
    Delete, Backspace,
    Unknown,
}

pub struct KeyReader {
    buffer: [u8; 256],
    pos: usize,
    len: usize,
}

impl KeyReader {
    pub fn new() -> Self {
        KeyReader {
            buffer: [0; 256],
            pos: 0,
            len: 0,
        }
    }

    pub fn read_key(&mut self) -> io::Result<Key> {
        // Try to read one or more bytes
        if self.pos >= self.len {
            self.len = io::stdin().read(&mut self.buffer)?;
            self.pos = 0;

            if self.len == 0 {
                return Ok(Key::Unknown);
            }
        }

        let byte = self.buffer[self.pos];
        self.pos += 1;

        // Handle escape sequences
        if byte == b'\x1b' {
            if self.pos >= self.len {
                self.len = io::stdin().read(&mut self.buffer)?;
                self.pos = 0;
            }

            if self.pos < self.len {
                let next = self.buffer[self.pos];
                self.pos += 1;

                if next == b'[' {
                    // CSI sequence
                    if self.pos >= self.len {
                        self.len = io::stdin().read(&mut self.buffer)?;
                        self.pos = 0;
                    }

                    if self.pos < self.len {
                        let code = self.buffer[self.pos];
                        self.pos += 1;

                        return Ok(match code {
                            b'A' => Key::Up,
                            b'B' => Key::Down,
                            b'C' => Key::Right,
                            b'D' => Key::Left,
                            b'H' => Key::Home,
                            b'F' => Key::End,
                            b'3' => {
                                // DEL key
                                if self.pos < self.len && self.buffer[self.pos] == b'~' {
                                    self.pos += 1;
                                }
                                Key::Delete
                            }
                            b'5' => {
                                // PageUp
                                if self.pos < self.len && self.buffer[self.pos] == b'~' {
                                    self.pos += 1;
                                }
                                Key::PageUp
                            }
                            b'6' => {
                                // PageDown
                                if self.pos < self.len && self.buffer[self.pos] == b'~' {
                                    self.pos += 1;
                                }
                                Key::PageDown
                            }
                            _ => Key::Unknown,
                        });
                    }
                } else if next == b'O' {
                    // SS3 sequence
                    if self.pos >= self.len {
                        self.len = io::stdin().read(&mut self.buffer)?;
                        self.pos = 0;
                    }

                    if self.pos < self.len {
                        let code = self.buffer[self.pos];
                        self.pos += 1;

                        return Ok(match code {
                            b'A' => Key::Up,
                            b'B' => Key::Down,
                            b'C' => Key::Right,
                            b'D' => Key::Left,
                            b'H' => Key::Home,
                            b'F' => Key::End,
                            _ => Key::Unknown,
                        });
                    }
                } else {
                    // Alt + key
                    return Ok(match next {
                        b'f' => Key::Alt(Box::new(Key::Char('f'))),
                        b'b' => Key::Alt(Box::new(Key::Char('b'))),
                        b'n' => Key::Alt(Box::new(Key::Char('n'))),
                        b'p' => Key::Alt(Box::new(Key::Char('p'))),
                        b'<' => Key::Alt(Box::new(Key::Char('<'))),
                        b'>' => Key::Alt(Box::new(Key::Char('>'))),
                        b'x' => Key::Alt(Box::new(Key::Char('x'))),
                        b'v' => Key::Alt(Box::new(Key::Char('v'))),
                        b'[' => Key::Alt(Box::new(Key::Char('['))),
                        b']' => Key::Alt(Box::new(Key::Char(']'))),
                        c if c >= 32 && c < 127 => Key::Alt(Box::new(Key::Char(c as char))),
                        _ => Key::Unknown,
                    });
                }
            }

            return Ok(Key::Escape);
        }

        // Handle control characters
        if byte < 32 {
            return Ok(match byte {
                1 => Key::CtrlA,
                2 => Key::CtrlB,
                3 => Key::CtrlC,
                4 => Key::CtrlD,
                5 => Key::CtrlE,
                6 => Key::CtrlF,
                7 => Key::CtrlG,
                8 => Key::CtrlH,
                9 => Key::CtrlI,
                10 => Key::CtrlJ,
                11 => Key::CtrlK,
                12 => Key::CtrlL,
                13 => Key::CtrlM,
                14 => Key::CtrlN,
                15 => Key::CtrlO,
                16 => Key::CtrlP,
                17 => Key::CtrlQ,
                18 => Key::CtrlR,
                19 => Key::CtrlS,
                20 => Key::CtrlT,
                21 => Key::CtrlU,
                22 => Key::CtrlV,
                23 => Key::CtrlW,
                24 => Key::CtrlX,
                25 => Key::CtrlY,
                26 => Key::CtrlZ,
                27 => Key::CtrlLeftBracket,
                28 => Key::CtrlRightBracket,
                _ => Key::Unknown,
            });
        }

        // Handle DEL
        if byte == 127 {
            return Ok(Key::Backspace);
