pub struct SearchState {
    pub query: String,
    pub current_match: Option<(usize, usize)>,
    pub is_active: bool,
}

impl SearchState {
    pub fn new() -> Self {
        SearchState {
            query: String::new(),
            current_match: None,
            is_active: false,
        }
    }

    pub fn search(&mut self, text: &[String]) -> Option<(usize, usize)> {
        if self.query.is_empty() {
            return None;
        }

        for (line_idx, line) in text.iter().enumerate() {
            if let Some(col_idx) = line.find(&self.query) {
                return Some((col_idx, line_idx));
            }
        }

        None
    }

    pub fn search_next(&mut self, text: &[String], start_line: usize, start_col: usize) -> Option<(usize, usize)> {
        if self.query.is_empty() {
            return None;
        }

        // Search from current position to end
        if start_line < text.len() {
            let line = &text[start_line];
            if let Some(col_idx) = line[start_col..].find(&self.query) {
                self.current_match = Some((start_col + col_idx, start_line));
                return self.current_match;
            }
        }

        // Search in remaining lines
        for (line_idx, line) in text.iter().enumerate().skip(start_line + 1) {
            if let Some(col_idx) = line.find(&self.query) {
                self.current_match = Some((col_idx, line_idx));
                return self.current_match;
            }
        }

        // Wrap around to beginning
        for (line_idx, line) in text.iter().enumerate() {
            if line_idx >= start_line {
                break;
            }
            if let Some(col_idx) = line.find(&self.query) {
                self.current_match = Some((col_idx, line_idx));
                return self.current_match;
            }
        }

        None
    }
}
