use std::collections::VecDeque;
use std::fs;
use std::io;

#[derive(Clone, Debug)]
pub enum EditAction {
    InsertChar { pos: (usize, usize), ch: char },
    DeleteChar { pos: (usize, usize), ch: char },
    InsertLine { line_idx: usize, content: String },
    DeleteLine { line_idx: usize, content: String },
    SplitLine { line_idx: usize, col: usize },
    MergeLine { line_idx: usize, content: String },
}

pub struct TextBuffer {
    pub lines: Vec<String>,
    pub cx: usize,
    pub cy: usize,
    pub filepath: Option<String>,
    pub is_dirty: bool,
    pub undo_stack: VecDeque<EditAction>,
    pub redo_stack: VecDeque<EditAction>,
    pub offset_y: usize,
}

impl TextBuffer {
    pub fn new() -> Self {
        TextBuffer {
            lines: vec![String::new()],
            cx: 0,
            cy: 0,
            filepath: None,
            is_dirty: false,
            undo_stack: VecDeque::new(),
            redo_stack: VecDeque::new(),
            offset_y: 0,
        }
    }

    pub fn from_file(filepath: String) -> io::Result<Self> {
        let content = fs::read_to_string(&filepath)?;
        let lines: Vec<String> = if content.is_empty() {
            vec![String::new()]
        } else {
            content.lines().map(|s| s.to_string()).collect()
        };

        Ok(TextBuffer {
            lines,
            cx: 0,
            cy: 0,
            filepath: Some(filepath),
            is_dirty: false,
            undo_stack: VecDeque::new(),
            redo_stack: VecDeque::new(),
            offset_y: 0,
        })
    }

    pub fn save(&mut self) -> io::Result<()> {
        if let Some(ref filepath) = self.filepath {
            let content = self.lines.join("\n");
            fs::write(filepath, content)?;
            self.is_dirty = false;
        }
        Ok(())
    }

    pub fn insert_char(&mut self, ch: char) {
        if self.cy >= self.lines.len() {
            self.lines.push(String::new());
        }

        let action = EditAction::InsertChar {
            pos: (self.cx, self.cy),
            ch,
        };

        let line = &mut self.lines[self.cy];
        if self.cx > line.len() {
            self.cx = line.len();
        }

        line.insert(self.cx, ch);
        self.cx += 1;
        self.is_dirty = true;
        self.redo_stack.clear();
        self.undo_stack.push_back(action);

        if self.undo_stack.len() > 1000 {
            self.undo_stack.pop_front();
        }
    }

    pub fn delete_char(&mut self) {
        if self.cy >= self.lines.len() {
            return;
        }

        let line = &mut self.lines[self.cy];
        if self.cx > 0 && self.cx <= line.len() {
            self.cx -= 1;
            let ch = line.remove(self.cx);

            let action = EditAction::DeleteChar {
                pos: (self.cx, self.cy),
                ch,
            };

            self.is_dirty = true;
            self.redo_stack.clear();
            self.undo_stack.push_back(action);

            if self.undo_stack.len() > 1000 {
                self.undo_stack.pop_front();
            }
        }
    }

    pub fn delete_next_char(&mut self) {
        if self.cy >= self.lines.len() {
            return;
        }

        let line = &mut self.lines[self.cy];
        if self.cx < line.len() {
            let ch = line.remove(self.cx);

            let action = EditAction::DeleteChar {
                pos: (self.cx, self.cy),
                ch,
            };

            self.is_dirty = true;
            self.redo_stack.clear();
            self.undo_stack.push_back(action);

            if self.undo_stack.len() > 1000 {
                self.undo_stack.pop_front();
            }
        }
    }

    pub fn delete_word(&mut self) {
        if self.cy >= self.lines.len() {
            return;
        }

        let line = &mut self.lines[self.cy];
        if self.cx == 0 {
            return;
        }

        let mut end = self.cx;
        while end > 0 && line.chars().nth(end - 1).map_or(false, |c| c.is_whitespace()) {
            end -= 1;
        }

        while end > 0 && !line.chars().nth(end - 1).map_or(false, |c| c.is_whitespace()) {
            end -= 1;
        }

        if end < self.cx {
            let _deleted = line.drain(end..self.cx).collect::<String>();
            self.cx = end;
            self.is_dirty = true;
            self.redo_stack.clear();
        }
    }

    pub fn delete_to_line_start(&mut self) {
        if self.cy >= self.lines.len() {
            return;
        }

        let line = &mut self.lines[self.cy];
        if self.cx > 0 {
            line.drain(0..self.cx);
            self.cx = 0;
            self.is_dirty = true;
            self.redo_stack.clear();
        }
    }

    pub fn delete_to_line_end(&mut self) {
        if self.cy >= self.lines.len() {
            return;
        }

        let line = &mut self.lines[self.cy];
        line.truncate(self.cx);
        self.is_dirty = true;
        self.redo_stack.clear();
    }

    pub fn new_line(&mut self) {
        if self.cy >= self.lines.len() {
            self.lines.push(String::new());
        }

        let line = &mut self.lines[self.cy];
        let new_line_content = line.split_off(self.cx);

        self.lines.insert(self.cy + 1, new_line_content);
        self.cy += 1;
        self.cx = 0;
        self.is_dirty = true;
        self.redo_stack.clear();
    }

    pub fn undo(&mut self) {
        if let Some(action) = self.undo_stack.pop_back() {
            match action.clone() {
                EditAction::InsertChar { pos: (x, y), ch: _ } => {
                    if y < self.lines.len() && x < self.lines[y].len() {
                        self.lines[y].remove(x);
                    }
                }
                EditAction::DeleteChar { pos: (x, y), ch } => {
                    if y < self.lines.len() {
                        self.lines[y].insert(x, ch);
                    }
                }
                EditAction::SplitLine { line_idx, col: _ } => {
                    if line_idx < self.lines.len() && line_idx + 1 < self.lines.len() {
                        let next = self.lines.remove(line_idx + 1);
                        self.lines[line_idx].push_str(&next);
                    }
                }
                EditAction::MergeLine { line_idx, content } => {
                    if line_idx < self.lines.len() {
                        self.lines.insert(line_idx + 1, content);
                    }
                }
                _ => {}
            }
            self.redo_stack.push_back(action);
        }
    }

    pub fn redo(&mut self) {
        if let Some(action) = self.redo_stack.pop_back() {
            match action.clone() {
                EditAction::InsertChar { pos: (x, y), ch } => {
                    if y < self.lines.len() {
                        self.lines[y].insert(x, ch);
                    }
                }
                EditAction::DeleteChar { pos: (x, y), ch: _ } => {
                    if y < self.lines.len() && x < self.lines[y].len() {
                        self.lines[y].remove(x);
                    }
                }
                EditAction::SplitLine { line_idx, col } => {
                    if line_idx < self.lines.len() {
                        let line = &mut self.lines[line_idx];
                        let new_line = line.split_off(col);
                        self.lines.insert(line_idx + 1, new_line);
                    }
                }
                EditAction::MergeLine { line_idx, content: _ } => {
                    if line_idx < self.lines.len() {
                        self.lines.remove(line_idx + 1);
                    }
                }
                _ => {}
            }
            self.undo_stack.push_back(action);
        }
    }

    pub fn move_cursor_up(&mut self) {
        if self.cy > 0 {
            self.cy -= 1;
            let line_len = self.lines.get(self.cy).map(|l| l.len()).unwrap_or(0);
            if self.cx > line_len {
                self.cx = line_len;
            }
        }
    }

    pub fn move_cursor_down(&mut self) {
        if self.cy + 1 < self.lines.len() {
            self.cy += 1;
            let line_len = self.lines.get(self.cy).map(|l| l.len()).unwrap_or(0);
            if self.cx > line_len {
                self.cx = line_len;
            }
        }
    }

    pub fn move_cursor_left(&mut self) {
        if self.cx > 0 {
            self.cx -= 1;
        } else if self.cy > 0 {
            self.cy -= 1;
            self.cx = self.lines.get(self.cy).map(|l| l.len()).unwrap_or(0);
        }
    }

    pub fn move_cursor_right(&mut self) {
        let line_len = self.lines.get(self.cy).map(|l| l.len()).unwrap_or(0);
        if self.cx < line_len {
            self.cx += 1;
        } else if self.cy + 1 < self.lines.len() {
            self.cy += 1;
            self.cx = 0;
        }
    }

    pub fn move_to_line_start(&mut self) {
        self.cx = 0;
    }

    pub fn move_to_line_end(&mut self) {
        self.cx = self.lines.get(self.cy).map(|l| l.len()).unwrap_or(0);
    }

    pub fn move_to_next_word(&mut self) {
        if self.cy >= self.lines.len() {
            return;
        }

        let line = &self.lines[self.cy];
        let chars: Vec<char> = line.chars().collect();

        // Skip current word
        while self.cx < chars.len() && !chars[self.cx].is_whitespace() {
            self.cx += 1;
        }

        // Skip whitespace
        while self.cx < chars.len() && chars[self.cx].is_whitespace() {
            self.cx += 1;
        }
    }

    pub fn move_to_prev_word(&mut self) {
        if self.cy >= self.lines.len() {
            return;
        }

        if self.cx == 0 {
            return;
        }

        self.cx -= 1;
        let line = &self.lines[self.cy];
        let chars: Vec<char> = line.chars().collect();

        // Skip whitespace backwards
        while self.cx > 0 && chars[self.cx].is_whitespace() {
            self.cx -= 1;
        }

        // Skip word backwards
        while self.cx > 0 && !chars[self.cx - 1].is_whitespace() {
            self.cx -= 1;
        }
    }

    pub fn move_to_next_paragraph(&mut self) {
        if self.cy + 1 >= self.lines.len() {
            self.cy = self.lines.len() - 1;
            return;
        }

        // Move past current line if not empty
        if !self.lines[self.cy].is_empty() {
            self.cy += 1;
        }

        // Skip empty lines
        while self.cy < self.lines.len() && self.lines[self.cy].is_empty() {
            self.cy += 1;
        }

        self.cx = 0;
    }

    pub fn move_to_prev_paragraph(&mut self) {
        if self.cy == 0 {
            return;
        }

        self.cy -= 1;

        // Skip empty lines backwards
        while self.cy > 0 && self.lines[self.cy].is_empty() {
            self.cy -= 1;
        }

        self.cx = 0;
    }

    pub fn move_to_file_start(&mut self) {
        self.cy = 0;
        self.cx = 0;
    }

    pub fn move_to_file_end(&mut self) {
        self.cy = if self.lines.is_empty() { 0 } else { self.lines.len() - 1 };
        self.cx = self.lines.get(self.cy).map(|l| l.len()).unwrap_or(0);
    }
}
