            self.cx = 0;
        }
    }

    pub fn move_to_line_start(&mut self) {
        self.cx = 0;
    }

    pub fn move_to_line_end(&mut self) {
        self.cx = self.lines.get(self.cy).map(|l| l.len()).unwrap_or(0);
    }

    pub fn move_to_next_word(&mut self) {
        if self.cy >= self.lines.len() {
            return;
        }

        let line = &self.lines[self.cy];
        let chars: Vec<char> = line.chars().collect();

        // Skip current word
        while self.cx < chars.len() && !chars[self.cx].is_whitespace() {
            self.cx += 1;
        }

        // Skip whitespace
        while self.cx < chars.len() && chars[self.cx].is_whitespace() {
            self.cx += 1;
        }
    }

    pub fn move_to_prev_word(&mut self) {
        if self.cy >= self.lines.len() {
            return;
        }

        if self.cx == 0 {
            return;
        }

        self.cx -= 1;
        let line = &self.lines[self.cy];
        let chars: Vec<char> = line.chars().collect();

        // Skip whitespace backwards
        while self.cx > 0 && chars[self.cx].is_whitespace() {
            self.cx -= 1;
        }

        // Skip word backwards
        while self.cx > 0 && !chars[self.cx - 1].is_whitespace() {
            self.cx -= 1;
        }
    }

