        if self.cy + 1 >= self.lines.len() {
            self.cy = self.lines.len() - 1;
            return;
        }

        // Move past current line if not empty
        if !self.lines[self.cy].is_empty() {
            self.cy += 1;
        }

        // Skip empty lines
        while self.cy < self.lines.len() && self.lines[self.cy].is_empty() {
            self.cy += 1;
        }

        self.cx = 0;
    }

    pub fn move_to_prev_paragraph(&mut self) {
        if self.cy == 0 {
            return;
        }

        self.cy -= 1;

        // Skip empty lines backwards
        while self.cy > 0 && self.lines[self.cy].is_empty() {
            self.cy -= 1;
        }

        self.cx = 0;
    }

    pub fn move_to_file_start(&mut self) {
        self.cy = 0;
        self.cx = 0;
    }

