use std::io;

pub struct Terminal {
    original_termios: TermIos,
}

#[repr(C)]
#[derive(Clone, Copy)]
struct TermIos {
    c_iflag: u32,
    c_oflag: u32,
    c_cflag: u32,
    c_lflag: u32,
    c_line: u8,
    c_cc: [u8; 32],
    c_ispeed: u32,
    c_ospeed: u32,
}

const STDIN_FILENO: i32 = 0;
const STDOUT_FILENO: i32 = 1;

const TCSAFLUSH: i32 = 2;

const ICANON: u32 = 0o0000002;
const ECHO: u32 = 0o0000010;
const ISIG: u32 = 0o0000001;
const IXON: u32 = 0o0002000;
const INPCK: u32 = 0o0000020;
const ISTRIP: u32 = 0o0000040;
const OPOST: u32 = 0o0000001;
const CS8: u32 = 0o0000060;
const VMIN: usize = 6;
const VTIME: usize = 5;

extern "C" {
    fn tcgetattr(fd: i32, termios_p: *mut TermIos) -> i32;
    fn tcsetattr(fd: i32, optional_actions: i32, termios_p: *const TermIos) -> i32;
    fn ioctl(fd: i32, request: u64, ...) -> i32;
}

#[repr(C)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

const TIOCGWINSZ: u64 = 0x5413;

impl Terminal {
    pub fn new() -> io::Result<Self> {
        // Get original terminal settings
        let mut original = TermIos {
            c_iflag: 0,
            c_oflag: 0,
            c_cflag: 0,
            c_lflag: 0,
            c_line: 0,
            c_cc: [0; 32],
            c_ispeed: 0,
            c_ospeed: 0,
        };

        if unsafe { tcgetattr(STDIN_FILENO, &mut original) } != 0 {
            return Err(io::Error::last_os_error());
        }

        let mut new_termios = original.clone();

        // Disable canonical mode and echo
        new_termios.c_lflag &= !(ICANON | ECHO | ISIG);
        new_termios.c_iflag &= !(IXON | INPCK | ISTRIP);
        new_termios.c_oflag &= !OPOST;
        new_termios.c_cflag |= CS8;
        new_termios.c_cc[VMIN] = 0;
        new_termios.c_cc[VTIME] = 0;

        // Set the new terminal settings
        if unsafe { tcsetattr(STDIN_FILENO, TCSAFLUSH, &new_termios) } != 0 {
            return Err(io::Error::last_os_error());
        }

        Ok(Terminal {
            original_termios: original,
        })
    }

    pub fn enable_raw_mode(&mut self) -> io::Result<()> {
        let mut termios = TermIos {
            c_iflag: 0,
            c_oflag: 0,
            c_cflag: 0,
            c_lflag: 0,
            c_line: 0,
            c_cc: [0; 32],
            c_ispeed: 0,
            c_ospeed: 0,
        };

        if unsafe { tcgetattr(STDIN_FILENO, &mut termios) } != 0 {
            return Err(io::Error::last_os_error());
        }

        termios.c_lflag &= !(ICANON | ECHO | ISIG);
        termios.c_iflag &= !(IXON | INPCK | ISTRIP);
        termios.c_oflag &= !OPOST;
        termios.c_cflag |= CS8;
        termios.c_cc[VMIN] = 0;
        termios.c_cc[VTIME] = 0;

        if unsafe { tcsetattr(STDIN_FILENO, TCSAFLUSH, &termios) } != 0 {
            return Err(io::Error::last_os_error());
        }

        Ok(())
    }

    pub fn get_size(&self) -> io::Result<(u16, u16)> {
        let mut ws = WinSize {
            ws_row: 0,
            ws_col: 0,
            ws_xpixel: 0,
            ws_ypixel: 0,
        };

        if unsafe { ioctl(STDOUT_FILENO, TIOCGWINSZ, &mut ws) } == 0 {
            Ok((ws.ws_col, ws.ws_row))
        } else {
            Err(io::Error::last_os_error())
        }
    }
}

impl Drop for Terminal {
    fn drop(&mut self) {
        // Restore original terminal settings
        let _ = unsafe { tcsetattr(STDIN_FILENO, TCSAFLUSH, &self.original_termios) };
    }
}
