use crate::terminal::Terminal;
use crate::buffer::TextBuffer;
use crate::keymaps::{Key, KeyReader};
use crate::search::SearchState;

pub struct Editor {
    buffers: Vec<TextBuffer>,
    current_buffer: usize,
    terminal: Terminal,
    screen_width: u16,
    screen_height: u16,
    key_reader: KeyReader,
    search_state: SearchState,
    mode: EditorMode,
    status_message: String,
}

#[derive(Debug, Clone, PartialEq)]
enum EditorMode {
    Normal,
    Search,
    Prompt,
}

impl Editor {
    pub fn new(file_paths: Vec<String>) -> io::Result<Self> {
        let mut terminal = Terminal::new()?;
        terminal.enable_raw_mode()?;

        let (width, height) = terminal.get_size()?;

        let mut buffers = Vec::new();

        // Load files or create new buffer
        if file_paths.is_empty() {
            buffers.push(TextBuffer::new());
        } else {
            for path in file_paths {
                match TextBuffer::from_file(path.clone()) {
                    Ok(buf) => buffers.push(buf),
                    Err(_) => {
                        // Create new buffer for file that doesn't exist yet
                        let mut buf = TextBuffer::new();
                        buf.filepath = Some(path);
                        buffers.push(buf);
                    }
                }
            }
        }

        let mut editor = Editor {
            buffers,
            current_buffer: 0,
            terminal,
            screen_width: width,
            screen_height: height,
            key_reader: KeyReader::new(),
            search_state: SearchState::new(),
            mode: EditorMode::Normal,
            status_message: String::new(),
        };

        editor.refresh_screen()?;

        Ok(editor)
    }

    pub fn run(&mut self) -> io::Result<()> {
        loop {
            let key = self.key_reader.read_key()?;

            match self.mode {
                EditorMode::Normal => {
                    if !self.handle_key_normal(key)? {
                        break; // Quit
                    }
                }
                EditorMode::Search => {
                    if !self.handle_key_search(key)? {
                        break;
                    }
                }
                _ => {}
            }

            self.refresh_screen()?;
        }

        Ok(())
    }

    fn handle_key_normal(&mut self, key: Key) -> io::Result<bool> {
        match key {
            Key::CtrlQ => return Ok(false), // Quit
            Key::CtrlS => {
                self.buffers[self.current_buffer].save()?;
                self.status_message = format!("Saved");
                return Ok(true);
            }
            Key::CtrlO => {
                // Open file - for now we'll skip this as it requires more complex logic
                self.status_message = format!("Open not implemented");
                return Ok(true);
            }
            Key::CtrlX => {
                // Next buffer
                if self.buffers.len() > 1 {
                    self.current_buffer = (self.current_buffer + 1) % self.buffers.len();
                }
                return Ok(true);
            }
            Key::Alt(ref k) if **k == Key::Char('x') => {
                // Previous buffer
                if self.buffers.len() > 1 {
                    self.current_buffer = if self.current_buffer == 0 {
                        self.buffers.len() - 1
                    } else {
                        self.current_buffer - 1
                    };
                }
                return Ok(true);
            }
            Key::CtrlP | Key::Up => {
                self.buffers[self.current_buffer].move_cursor_up();
            }
            Key::CtrlN | Key::Down => {
                self.buffers[self.current_buffer].move_cursor_down();
            }
            Key::CtrlF | Key::Right => {
                self.buffers[self.current_buffer].move_cursor_right();
            }
            Key::CtrlB | Key::Left => {
                self.buffers[self.current_buffer].move_cursor_left();
            }
            Key::CtrlA | Key::Home => {
                self.buffers[self.current_buffer].move_to_line_start();
            }
            Key::Alt(ref k) if **k == Key::Char('[') => {
                self.buffers[self.current_buffer].move_to_line_start();
            }
            Key::CtrlE | Key::End => {
                self.buffers[self.current_buffer].move_to_line_end();
            }
            Key::Alt(ref k) if **k == Key::Char(']') => {
                self.buffers[self.current_buffer].move_to_line_end();
            }
            Key::CtrlLeftBracket | Key::PageDown => {
                self.page_down();
            }
            Key::CtrlRightBracket | Key::PageUp => {
                self.page_up();
            }
            Key::Alt(ref k) if **k == Key::Char('f') => {
                self.buffers[self.current_buffer].move_to_next_word();
            }
            Key::Alt(ref k) if **k == Key::Char('b') => {
                self.buffers[self.current_buffer].move_to_prev_word();
            }
            Key::Alt(ref k) if **k == Key::Char('n') => {
                self.buffers[self.current_buffer].move_to_next_paragraph();
            }
            Key::Alt(ref k) if **k == Key::Char('p') => {
                self.buffers[self.current_buffer].move_to_prev_paragraph();
            }
            Key::Alt(ref k) if **k == Key::Char('<') => {
                self.buffers[self.current_buffer].move_to_file_start();
            }
            Key::Alt(ref k) if **k == Key::Char('>') => {
                self.buffers[self.current_buffer].move_to_file_end();
            }
            Key::CtrlH | Key::Backspace => {
                self.buffers[self.current_buffer].delete_char();
            }
            Key::CtrlD | Key::Delete => {
                self.buffers[self.current_buffer].delete_next_char();
            }
            Key::CtrlW => {
                self.buffers[self.current_buffer].delete_word();
            }
            Key::CtrlJ => {
                self.buffers[self.current_buffer].delete_to_line_start();
            }
            Key::CtrlK => {
                self.buffers[self.current_buffer].delete_to_line_end();
            }
            Key::CtrlU => {
                self.buffers[self.current_buffer].undo();
            }
            Key::CtrlR => {
                self.buffers[self.current_buffer].redo();
            }
            Key::CtrlG => {
                self.mode = EditorMode::Search;
                self.search_state.is_active = true;
                self.search_state.query.clear();
            }
            Key::CtrlM => {
                self.buffers[self.current_buffer].new_line();
            }
            Key::CtrlL => {
                // Refresh screen - already done in run loop
            }
            Key::Alt(ref k) if **k == Key::Char('?') => {
                // Show help - we can't really do this in a TUI app
                self.status_message = "Help: Ctrl-Q to quit".to_string();
            }
            Key::Char(c) => {
                self.buffers[self.current_buffer].insert_char(c);
                self.status_message.clear();
            }
            _ => {}
        }

        Ok(true)
    }

    fn handle_key_search(&mut self, key: Key) -> io::Result<bool> {
        match key {
            Key::CtrlM => {
                // Execute search
                let lines: Vec<String> = self.buffers[self.current_buffer].lines.clone();
                let cy = self.buffers[self.current_buffer].cy;
                let cx = self.buffers[self.current_buffer].cx;

                if let Some((col, line)) = self.search_state.search_next(
                    &lines,
                    cy,
                    cx,
                ) {
                    self.buffers[self.current_buffer].cy = line;
                    self.buffers[self.current_buffer].cx = col;
                }
                self.mode = EditorMode::Normal;
            }
            Key::CtrlLeftBracket | Key::Escape => {
                // Cancel search
                self.mode = EditorMode::Normal;
                self.search_state.query.clear();
            }
            Key::CtrlH | Key::Backspace => {
                self.search_state.query.pop();
            }
            Key::Char(c) => {
                self.search_state.query.push(c);
            }
            _ => {}
        }

        Ok(true)
    }

    fn page_down(&mut self) {
        let page_height = (self.screen_height.saturating_sub(2)) as usize;
        let buf = &mut self.buffers[self.current_buffer];

        buf.cy = std::cmp::min(buf.cy + page_height, buf.lines.len() - 1);
        buf.offset_y = std::cmp::min(buf.offset_y + page_height, buf.lines.len().saturating_sub(page_height));

        let line_len = buf.lines.get(buf.cy).map(|l| l.len()).unwrap_or(0);
        if buf.cx > line_len {
            buf.cx = line_len;
        }
    }

    fn page_up(&mut self) {
        let page_height = (self.screen_height.saturating_sub(2)) as usize;
        let buf = &mut self.buffers[self.current_buffer];

        if buf.cy >= page_height {
            buf.cy -= page_height;
        } else {
            buf.cy = 0;
        }

        if buf.offset_y >= page_height {
            buf.offset_y -= page_height;
        } else {
            buf.offset_y = 0;
        }

        let line_len = buf.lines.get(buf.cy).map(|l| l.len()).unwrap_or(0);
        if buf.cx > line_len {
            buf.cx = line_len;
        }
    }

    fn refresh_screen(&mut self) -> io::Result<()> {
        let stdout = io::stdout();
        let mut handle = stdout.lock();

        // Clear screen
        write!(handle, "\x1b[2J")?; // Clear entire screen
        write!(handle, "\x1b[H")?;  // Move cursor to top-left

        let buf = &self.buffers[self.current_buffer];

        // Content area: screen_height - 2 (for status and help lines)
        let content_height = if self.screen_height >= 2 {
            (self.screen_height - 2) as usize
        } else {
            0
        };

        // Calculate which lines to display
        let start_line = buf.offset_y;
        let end_line = std::cmp::min(start_line + content_height, buf.lines.len());

        // Display lines
        for line_idx in start_line..end_line {
            if line_idx < buf.lines.len() {
                let line = &buf.lines[line_idx];
                write!(handle, "{}", line)?;
            }
            write!(handle, "\r\n")?;
        }

        // Fill remaining content area with ~
        for _ in (end_line - start_line)..content_height {
            write!(handle, "~\r\n")?;
        }

        // Status bar
        let modified_status = if buf.is_dirty { "(modified)" } else { "" };
        let filename = buf.filepath.as_ref()
            .map(|p| {
                let parts: Vec<&str> = p.split('/').collect();
                parts.last().map(|s| s.to_string()).unwrap_or_else(|| p.clone())
            })
            .unwrap_or_else(|| "[No Name]".to_string());

        let total_buffers = self.buffers.len();
        let buffer_num = self.current_buffer + 1;
        let total_lines = buf.lines.len();
        let current_line = buf.cy + 1;

        let status_str = format!(
            "\"{}\" - {}/{} {} plain {}/{}",
            filename, buffer_num, total_buffers, modified_status, current_line, total_lines
        );

        // Write status
        write!(handle, "{}", status_str)?;

        // Pad status bar to screen width with spaces
        let padding = self.screen_width as usize - status_str.len();
        for _ in 0..padding {
            write!(handle, " ")?;
        }
        write!(handle, "\r\n")?;

        // Help line
        write!(handle, "Ctrl-? for help")?;

        // Move cursor to buffer position - DO THIS LAST
        let display_cy = (buf.cy - start_line + 1) as u16;
        let display_cx = (buf.cx + 1) as u16;
        write!(handle, "\x1b[{};{}H", display_cy, display_cx)?;

        handle.flush()?;
        Ok(())
    }
}
